package com.overhealsave;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Overheal Save",
	description = "Warns when overheal HP is about to decay so you can flick rapid heal to reset the timer.",
	tags = {"combat", "hp", "health", "hitpoints", "prayer", "regen", "overheal", "save", "decay", "rapid", "heal", "pvm", "pvp", "orb"}
)
public class OverhealSavePlugin extends Plugin
{
	private static final int HP_REGEN_TICKS = 100;
	private static final int HP_REGEN_TICKS_RAPID = 50;

	@Inject
	private Client client;

	@Inject
	private Notifier notifier;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private OverhealSaveConfig config;

	@Inject
	private HpOrbOverlay hpOrbOverlay;

	@Inject
	private PrayerRingOverlay prayerRingOverlay;

	private int ticksSinceHpRegen = -2;
	private boolean prevWarningActive;

	// False when the plugin is enabled mid-session: we can't know the regen
	// cycle phase until a deterministic reset (login, hop, or Rapid Heal flick).
	@Getter
	private boolean timerKnown;

	@Getter
	private boolean warningActive;

	@Getter
	private boolean overhealed;

	@Getter
	private boolean atFullHp;

	@Getter
	private double decayProgress;

	@Provides
	OverhealSaveConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OverhealSaveConfig.class);
	}

	@Override
	protected void startUp()
	{
		ticksSinceHpRegen = -2;
		// Enabled mid-session (already logged in) ⇒ indeterminate. Enabled at the
		// login screen / fresh start ⇒ the upcoming login is a valid sync point.
		timerKnown = client.getGameState() != GameState.LOGGED_IN;
		prevWarningActive = false;
		warningActive = false;
		overhealed = false;
		atFullHp = false;
		decayProgress = 0;
		overlayManager.add(hpOrbOverlay);
		overlayManager.add(prayerRingOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(hpOrbOverlay);
		overlayManager.remove(prayerRingOverlay);
		warningActive = false;
		prevWarningActive = false;
		overhealed = false;
		atFullHp = false;
		decayProgress = 0;
	}

	@Subscribe
	private void onGameStateChanged(GameStateChanged ev)
	{
		if (ev.getGameState() == GameState.HOPPING || ev.getGameState() == GameState.LOGIN_SCREEN)
		{
			ticksSinceHpRegen = -2;
			// Logout/hop edge: the next login resets the in-game regen timer, so we
			// re-sync. This edge never fires on a region load, so indeterminate is
			// preserved across teleports.
			timerKnown = true;
			prevWarningActive = false;
			warningActive = false;
			overhealed = false;
			atFullHp = false;
			decayProgress = 0;
		}
	}

	@Subscribe
	private void onVarbitChanged(VarbitChanged ev)
	{
		if (ev.getVarbitId() == VarbitID.PRAYER_RAPIDHEAL)
		{
			// Flicking Rapid Heal resets the in-game regen timer: a deterministic sync.
			ticksSinceHpRegen = 0;
			timerKnown = true;
		}
	}

	@Subscribe
	private void onGameTick(GameTick ev)
	{
		final boolean rapidHealActive = client.getVarbitValue(VarbitID.PRAYER_RAPIDHEAL) == 1;
		final int cycleLen = rapidHealActive ? HP_REGEN_TICKS_RAPID : HP_REGEN_TICKS;
		ticksSinceHpRegen = (ticksSinceHpRegen + 1) % cycleLen;

		final int currentHp = client.getBoostedSkillLevel(Skill.HITPOINTS);
		final int maxHp = client.getRealSkillLevel(Skill.HITPOINTS);
		overhealed = currentHp > maxHp;
		atFullHp = currentHp == maxHp;

		final int effectiveLead = Math.min(config.leadTicks(), cycleLen);
		final boolean inLeadWindow = ticksSinceHpRegen >= cycleLen - effectiveLead;

		warningActive = timerKnown && overhealed && inLeadWindow;
		decayProgress = timerKnown && (overhealed || atFullHp) && ticksSinceHpRegen >= 0
			? 1.0 - (double) ticksSinceHpRegen / cycleLen
			: 0;

		if (warningActive && !prevWarningActive && config.enableSound() && rapidHealUsable())
		{
			final double seconds = (cycleLen - ticksSinceHpRegen) * 0.6;
			notifier.notify(String.format("Overheal decay in ~%.1fs — flick rapid heal!", seconds));
		}

		prevWarningActive = warningActive;
	}

	// During an active LMS match the Rapid Heal prayer is disabled and cannot be
	// toggled, so the overheal-save flick is impossible and warning the player is
	// pointless. BR_INGAME (LMS's internal "BringItOn" name) is 1 only inside a
	// match (0 in the lobby / on normal worlds), so this doesn't over-suppress
	// merely for being on an LMS world.
	private boolean rapidHealUsable()
	{
		return client.getVarbitValue(VarbitID.BR_INGAME) == 0;
	}
}

package com.overhealsave;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("overhealsave")
public interface OverhealSaveConfig extends Config
{
	@ConfigItem(
		keyName = "enableSound",
		name = "Notification sound",
		description = "Play a notification when overheal decay is imminent.",
		position = 0
	)
	default boolean enableSound()
	{
		return false;
	}

	@ConfigItem(
		keyName = "enableOrbRing",
		name = "Flash HP orb",
		description = "Show a pulsing ring outside the hitpoints orb during the warning window.",
		position = 1
	)
	default boolean enableOrbRing()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showRingAtFullHp",
		name = "Show ring at full HP",
		description = "Also show the hitpoints orb ring when at full HP, not only when overhealed.",
		position = 2
	)
	default boolean showRingAtFullHp()
	{
		return true;
	}

	@ConfigItem(
		keyName = "enablePrayerRing",
		name = "Highlight Rapid Heal",
		description = "Show a pulsing ring around the Rapid Heal prayer icon during the warning window.",
		position = 3
	)
	default boolean enablePrayerRing()
	{
		return true;
	}

	@ConfigItem(
		keyName = "prayerRingOnlyInLeadWindow",
		name = "Rapid Heal ring only in lead window",
		description = "Only show the Rapid Heal prayer ring during the warning lead window, not for the whole overheal cycle.",
		position = 4
	)
	default boolean prayerRingOnlyInLeadWindow()
	{
		return false;
	}

	@Range(min = 1, max = 100)
	@ConfigItem(
		keyName = "leadTicks",
		name = "Warning lead (ticks)",
		description = "Game ticks before the decay tick to start warning. 1 tick = 0.6s.",
		position = 5
	)
	default int leadTicks()
	{
		return 25;
	}
}

package com.overhealsave;

import java.awt.Color;

final class OverhealSaveColors
{
	private static final Color BASE = brighter(0x9B0703);
	private static final Color FLASH = Color.ORANGE;
	private static final long PULSE_HALF_PERIOD_MS = 400L;

	private OverhealSaveColors()
	{
	}

	static Color arcColor(boolean flashing)
	{
		if (!flashing)
		{
			return BASE;
		}
		long phase = (System.currentTimeMillis() / PULSE_HALF_PERIOD_MS) & 1L;
		return phase == 0 ? BASE : FLASH;
	}

	private static Color brighter(int color)
	{
		float[] hsv = new float[3];
		Color.RGBtoHSB(color >>> 16, (color >> 8) & 0xFF, color & 0xFF, hsv);
		return Color.getHSBColor(hsv[0], 1f, 1f);
	}
}

package com.overhealsave;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.geom.Arc2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class PrayerRingOverlay extends Overlay
{
	private static final int RING_PADDING = 4;
	private static final Stroke ARC_STROKE = new BasicStroke(2f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER);

	private final Client client;
	private final OverhealSavePlugin plugin;
	private final OverhealSaveConfig config;

	@Inject
	PrayerRingOverlay(Client client, OverhealSavePlugin plugin, OverhealSaveConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.enablePrayerRing() || !plugin.isOverhealed())
		{
			return null;
		}

		final double sweepProgress;
		final boolean flashing;
		if (!plugin.isTimerKnown())
		{
			// Indeterminate: full pulsing ring as a call-to-action to flick.
			// The lead-window gate doesn't apply — there's no accurate window.
			sweepProgress = 1.0;
			flashing = true;
		}
		else
		{
			if (config.prayerRingOnlyInLeadWindow() && !plugin.isWarningActive())
			{
				return null;
			}
			sweepProgress = plugin.getDecayProgress();
			flashing = plugin.isWarningActive();
		}

		Widget rapidHeal = findRapidHealWidget();
		if (rapidHeal == null || rapidHeal.isHidden())
		{
			return null;
		}

		Rectangle bounds = rapidHeal.getBounds();
		if (bounds.width <= 0 || bounds.height <= 0)
		{
			return null;
		}

		double diameter = Math.max(bounds.width, bounds.height) + RING_PADDING * 2.0;
		double cx = bounds.x + bounds.width / 2.0;
		double cy = bounds.y + bounds.height / 2.0;
		Arc2D.Double arc = new Arc2D.Double(cx - diameter / 2.0, cy - diameter / 2.0, diameter, diameter,
			90.0, -360.0 * sweepProgress, Arc2D.OPEN);

		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setStroke(ARC_STROKE);
		g.setColor(OverhealSaveColors.arcColor(flashing));
		g.draw(arc);
		return null;
	}

	private Widget findRapidHealWidget()
	{
		Widget root = client.getWidget(InterfaceID.Prayerbook.UNIVERSE);
		if (root == null || root.isHidden())
		{
			return null;
		}
		return walkForSprite(root);
	}

	private Widget walkForSprite(Widget w)
	{
		if (w == null)
		{
			return null;
		}
		int sprite = w.getSpriteId();
		if (sprite == SpriteID.Prayeron.RAPID_HEAL || sprite == SpriteID.Prayeroff.RAPID_HEAL_DISABLED)
		{
			return w;
		}
		Widget result;
		Widget[] dyn = w.getDynamicChildren();
		if (dyn != null)
		{
			for (Widget c : dyn)
			{
				if ((result = walkForSprite(c)) != null)
				{
					return result;
				}
			}
		}
		Widget[] stat = w.getStaticChildren();
		if (stat != null)
		{
			for (Widget c : stat)
			{
				if ((result = walkForSprite(c)) != null)
				{
					return result;
				}
			}
		}
		Widget[] nest = w.getNestedChildren();
		if (nest != null)
		{
			for (Widget c : nest)
			{
				if ((result = walkForSprite(c)) != null)
				{
					return result;
				}
			}
		}
		return null;
	}
}

package com.overhealsave;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.geom.Arc2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class HpOrbOverlay extends Overlay
{
	private static final double ORB_DIAMETER = 26D;
	private static final int ORB_OFFSET = 27;
	private static final Stroke ARC_STROKE = new BasicStroke(2f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER);

	private final Client client;
	private final OverhealSavePlugin plugin;
	private final OverhealSaveConfig config;

	@Inject
	HpOrbOverlay(Client client, OverhealSavePlugin plugin, OverhealSaveConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		// Render on top of the Regeneration Meter plugin, which also draws an
		// arc on the HP orb. Both default to PRIORITY_DEFAULT; for DYNAMIC
		// overlays a higher priority draws later (on top).
		setPriority(Overlay.PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.enableOrbRing())
		{
			return null;
		}

		final boolean visible;
		final double sweepProgress;
		final boolean flashing;
		if (!plugin.isTimerKnown())
		{
			// Indeterminate: regen phase unknown. Show a full pulsing ring only when
			// overhealed (never at full HP — no inaccurate countdown), prompting a flick.
			visible = plugin.isOverhealed();
			sweepProgress = 1.0;
			flashing = true;
		}
		else
		{
			final boolean showAtFullHp = plugin.isAtFullHp() && config.showRingAtFullHp();
			visible = plugin.isOverhealed() || showAtFullHp;
			sweepProgress = plugin.getDecayProgress();
			flashing = plugin.isWarningActive();
		}

		if (!visible)
		{
			return null;
		}

		Widget orb = client.getWidget(InterfaceID.Orbs.ORB_HEALTH);
		if (orb == null || orb.isHidden())
		{
			orb = client.getWidget(InterfaceID.OrbsNomap.ORB_HEALTH);
		}
		if (orb == null || orb.isHidden())
		{
			return null;
		}

		Rectangle bounds = orb.getBounds();
		double x = bounds.x + ORB_OFFSET;
		double y = bounds.y + (bounds.height / 2.0 - ORB_DIAMETER / 2.0);

		Arc2D.Double arc = new Arc2D.Double(x, y, ORB_DIAMETER, ORB_DIAMETER,
			90.0, -360.0 * sweepProgress, Arc2D.OPEN);

		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setStroke(ARC_STROKE);
		g.setColor(OverhealSaveColors.arcColor(flashing));
		g.draw(arc);
		return null;
	}
}
